class Counter:
    def advance(self):
        """Increase the stored count by one."""
        self.count += 1
        return self.count

class Buffer:
    def clear(self):
        """Discard every item currently held here."""
        self.items.clear()

class Reader:
    def read(self):
        """Fetch another chunk from the stream."""
        return self.stream.read(64)

class Connection:
    def close(self):
        """Release the socket owned by this connection."""
        self.socket.close()

class Registry:
    def register(self, manager):
        """Make this registry available to the manager."""
        manager.attach(self)

class Display:
    def render(self):
        """Format the current title for terminal output."""
        return '{}'.format(self.title)

class Endpoint:
    def describe(self):
        """The selected address is available through self.address."""
        return self.address

class Session:
    def refresh(self):
        """Reload credentials before checking the current session."""
        self.reload()
        return self.validate()

