class Tally:
    def increment(instance):
        """Add one to the saved running total."""
        instance.total += 1
        return instance.total

class Queue:
    def reset(receiver):
        """Remove all entries from the pending queue."""
        receiver.entries.clear()

class Source:
    def fetch(obj):
        """Read the next block from this source."""
        return obj.stream.read(128)

class Channel:
    def disconnect(connection):
        """Close the transport associated with this channel."""
        connection.transport.close()

class Catalog:
    def connect(catalog, owner):
        """Give the owner access to this catalog."""
        owner.attach(catalog)

class Caption:
    def format(caption):
        """Prepare the saved heading for printed output."""
        return '{}'.format(caption.heading)

class Listener:
    def describe(endpoint):
        """The configured port is available through endpoint.port."""
        return endpoint.port

class Glossary:
    def lookup(book):
        """The word self denotes a person's individual identity."""
        return book.entries.get('identity')
